/**
 * ctaLogo — Brand-stamp closer.
 *
 * Logo (or brand wordmark when no logo is uploaded) centered in the frame.
 * URL or fallback CTA text sits directly below. Background is media when
 * a mediaUrl is provided, otherwise the standard brand-color gradient
 * (same SceneBackground pipeline as `media` and `ctaMedia`).
 *
 * The Apple-style sign-off: identity + address, nothing else. Pick this
 * when the rest of the video did the talking and the close just needs to
 * stamp who and where.
 *
 * FX: shared SPRING_SMOOTH "land" curve over [0, 0.85].
 *  - Logo: fade + zoom 0.94 → 1.08
 *  - Wordmark fallback: same fade + zoom + letter-spacing collapse
 *    (0.4em → -0.02em) — type slowly tightens into place
 *  - URL: fade + scale + matching letter-spacing collapse (0.3em → 0.01em)
 */

import React from "react";
import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import { resolveTokens } from "./tokens";
import {
  SceneBackground,
  mediaBackgroundSchemaFields,
  mediaBackgroundDefaults,
} from "./scene-background";
import { WordmarkReveal } from "../primitives/typography/WordmarkReveal";

export const ctaLogoSchema: Record<string, VariableField> = {
  brandName: {
    type: "string",
    label: "Brand name",
    default: "YourBrand",
    required: true,
    description: "Shown as a wordmark when no logo is uploaded.",
  },
  url: {
    type: "string",
    label: "URL",
    default: "yoursite.com",
    description: "URL shown below the logo. Leave empty to fall back to CTA text.",
  },
  cta: {
    type: "string",
    label: "CTA fallback",
    default: "",
    description: "Optional. Shown ONLY when url is empty — use for 'Coming soon', 'Available now', etc. Leave empty when a URL is set; it would never render.",
  },
  ...mediaBackgroundSchemaFields,
  textColor: {
    type: "color",
    label: "Text color",
    default: "",
    description: "Override text color (leave empty for white).",
  },
};

export const ctaLogoDefaults: Record<string, unknown> = {
  brandName: "VanillaSky",
  url: "yoursite.com",
  cta: "",
  ...mediaBackgroundDefaults,
  textColor: "",
};

export const CtaLogoTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  width,
  height,
  sceneDuration,
  isPlaying,
}) => {
  const s = Math.min(width, height) / 1080;
  const { content, font } = resolveTokens(style);
  const textColor = String(variables.textColor || "") || content;

  const brandName = String(variables.brandName || "");
  const url = String(variables.url || "");
  const cta = String(variables.cta || "");
  const logoUrl = style.brandKit?.logoDataUrl || "";
  const mediaUrl = String(variables.mediaUrl || "");
  const mediaType = String(variables.mediaType || "auto");

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: "#000",
        position: "relative",
        overflow: "hidden",
        fontFamily: font,
      }}
    >
      {/* [slot: background] Media when set, brand gradient otherwise. */}
      <SceneBackground
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        width={width}
        height={height}
        mediaUrl={mediaUrl}
        mediaType={mediaType}
        mediaPoster={String(variables.mediaPoster || "")}
        seed={brandName}
        isPlaying={isPlaying}
      />

      {/* [slot: hero] Centered wordmark stack — WordmarkReveal primitive
          (provides its own positioned wrapper and motion; the brand name IS
          the text, so there is no separate caption slot). */}
      <WordmarkReveal
        progress={progress}
        brandName={brandName}
        url={url}
        cta={cta}
        logoUrl={logoUrl}
        width={width}
        height={height}
        font={font}
        textColor={textColor}
      />
    </div>
  );
};

// Unused import suppression — s was used inline for sizes before extraction,
// now WordmarkReveal computes its own scale factor.
void 0;

/**
 * SceneBackground — shared backdrop component for any scene template that
 * wants to support both a brand-color gradient and stock media (Pexels
 * photo / video) as an alternate atmosphere.
 *
 * Usage:
 *   <SceneBackground
 *     style={style}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     mediaUrl={String(variables.mediaUrl || "")}
 *     mediaType={String(variables.mediaType || "auto")}
 *     seed={String(variables.texts || "")}
 *     isPlaying={isPlaying}
 *   />
 *   ... template's content layered on top
 *
 * Behavior:
 *   - Brand gradient is the always-on backdrop (uses BrandGradientOverlay).
 *   - When mediaUrl is set and mediaType isn't "gradient", the photo/video
 *     covers the gradient. Vignette + bottom-half darken give the content
 *     contrast against busy footage.
 *   - mediaType="gradient" deliberately ignores mediaUrl and renders only
 *     the brand gradient. First-class atmospheric mode.
 *   - When mediaUrl is empty / 404s / Pexels search returned nothing,
 *     gradient shows through cleanly (matches every other gradient-backed
 *     template).
 *
 * Extracted from bg-media.tsx so any template can compose it. bg-media
 * now uses this component too — its "media is the scene" identity comes
 * from how it positions the title (centered, full-frame), not from
 * duplicated render logic.
 */

import React, { useEffect, useRef } from "react";
import type { GlobalStyle, VariableField } from "../video-config";
import { BrandGradientOverlay } from "./color-utils";
import { getBackgroundTransform } from "./background-effect";

const VIDEO_EXTENSIONS = [".mp4", ".webm", ".mov", ".m4v", ".avi"];

function isVideoUrl(url: string): boolean {
  try {
    const pathname = new URL(url).pathname.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => pathname.endsWith(ext));
  } catch {
    const lower = url.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => lower.endsWith(ext));
  }
}

export type ResolvedMediaType = "photo" | "video" | "gradient";

export function resolveMediaType(
  mediaType: string,
  mediaUrl: string,
): ResolvedMediaType {
  if (mediaType === "gradient") return "gradient";
  if (mediaType === "video") return "video";
  if (mediaType === "photo") return "photo";
  // "auto" — detect from URL extension
  return mediaUrl && isVideoUrl(mediaUrl) ? "video" : "photo";
}

/**
 * Standard schema fields any template can spread into its variableSchema
 * to enable media backgrounds. Keeps the field set + descriptions
 * consistent across templates.
 */
export const mediaBackgroundSchemaFields: Record<string, VariableField> = {
  mediaUrl: {
    type: "media",
    label: "Background media",
    description: "Optional photo or video URL behind this scene. When set, replaces the brand gradient.",
  },
  mediaKeyword: {
    type: "string",
    label: "Background search keyword",
    default: "",
    description: "2-4 word English term for Pexels stock-footage search (auto-fills mediaUrl).",
  },
  mediaType: {
    type: "enum",
    label: "Background media type",
    default: "auto",
    description: "auto detects photo/video from URL. 'gradient' is a deliberate mode — atmospheric brand-color scene with no stock footage.",
    options: ["auto", "photo", "video", "gradient"],
  },
  mediaPoster: {
    type: "string",
    label: "Background poster image",
    default: "",
    description: "Still image URL shown while a video backdrop is decoding its first frame. Auto-filled from Pexels' thumbnail when fillPexelsUrls sets a video mediaUrl. Hides the gradient flash that would otherwise appear in the ~50–400ms gap between a <video> mounting and decoding its first frame.",
  },
};

/** Default values for the media-background fields. Spread into a template's defaults. */
export const mediaBackgroundDefaults: Record<string, unknown> = {
  mediaUrl: "",
  mediaKeyword: "",
  mediaType: "auto",
  mediaPoster: "",
};

export interface SceneBackgroundProps {
  style: GlobalStyle;
  progress: number;
  sceneDuration?: number;
  width: number;
  height: number;
  mediaUrl?: string;
  mediaType?: string;
  /** Still image URL shown while the <video> backdrop decodes its first
   *  frame. Without it the element renders transparent during the
   *  ~50–400ms decode window and the gradient flashes through. */
  mediaPoster?: string;
  /** Background motion effect (drift / pulse / Ken Burns). Applied to the photo/video. */
  backgroundEffect?: string;
  /** Stable seed for the gradient breathing animation. Pass the scene's
   *  text content (or any stable string) — it's hashed deterministically. */
  seed?: number | string;
  /** Pause video when preview is paused. Defaults to true (export path). */
  isPlaying?: boolean;
  beatIntensity?: number;
}

export const SceneBackground: React.FC<SceneBackgroundProps> = ({
  style,
  progress,
  sceneDuration,
  width: _width,  // accepted for symmetry; not currently used in render
  height,
  mediaUrl = "",
  mediaType = "auto",
  mediaPoster,
  backgroundEffect,
  seed,
  isPlaying = true,
  beatIntensity = 0,
}) => {
  void _width;
  const resolved = resolveMediaType(mediaType, mediaUrl);
  const showMedia = resolved !== "gradient" && !!mediaUrl;

  const gradSeed = typeof seed === "number"
    ? seed
    : typeof seed === "string"
      ? seed.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0)
      : 0;

  const bgTransform = getBackgroundTransform(backgroundEffect, progress, beatIntensity);

  // Video playback control — same pause/seek logic bg-media used pre-extract.
  const videoRef = useRef<HTMLVideoElement>(null);
  const lastProgress = useRef(progress);
  const videoStarted = useRef(false);

  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;
    if (!isPlaying) {
      vid.pause();
      videoStarted.current = false;
      return;
    }
    const progressChanged = Math.abs(progress - lastProgress.current) > 0.001;
    lastProgress.current = progress;
    if (progressChanged && !videoStarted.current) {
      vid.playbackRate = 1;
      vid.currentTime = 0;
      vid.play().catch(() => {});
      videoStarted.current = true;
    } else if (!progressChanged && videoStarted.current) {
      vid.pause();
      videoStarted.current = false;
    }
  }, [progress, isPlaying]);

  // Release the decoder on unmount. Without this, iOS Safari keeps the
  // video's decoder buffer alive after the React node is gone — each
  // scene transition (or play/pause/play cycle that remounts the active
  // scene) leaks one decoder, eventually crossing the renderer's memory
  // ceiling and triggering "A problem repeatedly occurred." Same recipe
  // as #409's CanvasPreview preload cleanup: pause → clear src → load().
  // Capture the ref at mount-time so the cleanup uses the same node we
  // mounted (the ref's .current is stale by unmount).
  useEffect(() => {
    const vid = videoRef.current;
    return () => {
      if (!vid) return;
      vid.pause();
      vid.removeAttribute("src");
      vid.load();
    };
  }, []);

  return (
    <>
      <BrandGradientOverlay
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        seed={gradSeed}
      />

      {showMedia && (resolved === "video" ? (
        <video
          ref={videoRef}
          src={mediaUrl}
          // Poster paints during the decode window so the user sees the
          // (still) first frame instead of a transparent <video> letting
          // the brand gradient show through. Pexels returns a thumbnail
          // image alongside each video; fillPexelsUrls stores it in
          // `variables.mediaPoster`. Layered defense alongside preload="auto"
          // below: on desktop the byte preloader makes decode fast, on
          // mobile (where the preloader skips video pre-mounting to dodge
          // the iOS Safari memory crash) the poster is the primary shield.
          poster={mediaPoster || undefined}
          muted
          loop
          playsInline
          // preload="auto" — without it, browsers default to "metadata":
          // they only load the container/dimensions, not the byte stream
          // needed to decode frames. The element then renders transparent
          // until the first decoded frame arrives, letting the brand
          // gradient flash through whenever a scene mid-playback transitions
          // to a media backdrop. The parent preloader caches the bytes, but
          // decoder state is per-element, so the active mount still has to
          // decode the first frame; "auto" kicks that work off the instant
          // the element mounts.
          preload="auto"
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            transform: bgTransform.transform,
            transformOrigin: bgTransform.transformOrigin,
          }}
        />
      ) : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: bgTransform.transform,
            transformOrigin: bgTransform.transformOrigin,
            backgroundImage: `url(${mediaUrl})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
      ))}

      {showMedia && (
        <>
          {/* Vignette — gives the content contrast against busy footage. */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.55) 80%, rgba(0,0,0,0.75) 100%)",
              pointerEvents: "none",
            }}
          />
          {/* Center-text scrim — soft elliptical darken where headlines /
              wordStagger words / metrics typically land. Subtle (max ~22%
              darken at the focal point) so the photo still reads bright at
              the edges, but text on busy bg gets reliable contrast without
              relying on heavier shadows. */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(ellipse 85% 50% at 50% 50%, rgba(0,0,0,0.22) 0%, rgba(0,0,0,0.10) 50%, transparent 80%)",
              pointerEvents: "none",
            }}
          />
          {/* Bottom-half darken — improves text readability on photos. */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0,
              height: height * 0.45,
              background:
                "linear-gradient(to top, rgba(0,0,0,0.5) 0%, transparent 100%)",
              pointerEvents: "none",
            }}
          />
        </>
      )}
    </>
  );
};

/**
 * Background motion effects for templates.
 *
 * Applied to the background layer (media, gradient) throughout the entire scene.
 * Continuous motion — not tied to text timing.
 *
 * Templates with usesGlobalBackgroundEffect: true consume the video-level default.
 *
 * 9 effects, each with a distinct mood:
 * - static:        No motion — intentional stillness
 * - slow-zoom-in:  Draw attention inward, build focus
 * - slow-zoom-out: Reveal, establish, pull back
 * - ken-burns:     Classic cinematic photo motion (zoom + pan, direction alternates per scene)
 * - drift:         Gentle lateral pan (direction alternates per scene)
 * - pulse:         Beat-synced energy
 * - breathe:       Ambient dreamy float
 * - slow-tilt:     Tension, Dutch angle drift
 * - camera-shake:  Intensity, handheld drama
 */

import { interpolate } from "../react-animations/animation-utils";

export interface BackgroundTransform {
  transform: string;
  transformOrigin: string;
}

export const BACKGROUND_EFFECTS = [
  "static",
  "slow-zoom-in",
  "slow-zoom-out",
  "ken-burns",
  "drift",
  "pulse",
  "breathe",
  "slow-tilt",
  "camera-shake",
] as const;

type BackgroundEffectName = (typeof BACKGROUND_EFFECTS)[number];

// ─── Directional variant helpers ────────────────────────────────
// Ken Burns and Drift have internal direction variants that alternate
// by scene index to create visual variety across a video.

type Direction = "right" | "left" | "up" | "down";
const DIRECTIONS: Direction[] = ["right", "left", "up", "down"];

function getKenBurnsTransform(progress: number, direction: Direction): BackgroundTransform {
  const scale = interpolate(progress, [0, 1], [1.05, 1.15]);
  const mainAxis = direction === "right" || direction === "left";
  const sign = direction === "right" || direction === "down" ? 1 : -1;
  const primary = interpolate(progress, [0, 1], [-2 * sign, 2 * sign]);
  const secondary = interpolate(progress, [0, 1], [-0.5, 0.5]);

  const x = mainAxis ? primary : secondary;
  const y = mainAxis ? secondary : primary;

  return {
    transform: `scale(${scale}) translate(${x}%, ${y}%)`,
    transformOrigin: "center",
  };
}

function getDriftTransform(progress: number, direction: Direction): BackgroundTransform {
  const horizontal = direction === "right" || direction === "left";
  const sign = direction === "right" || direction === "down" ? 1 : -1;
  const offset = interpolate(progress, [0, 1], [-2 * sign, 2 * sign]);

  return {
    transform: horizontal
      ? `scale(1.1) translateX(${offset}%)`
      : `scale(1.1) translateY(${offset}%)`,
    transformOrigin: "center",
  };
}

// ─── Public API ─────────────────────────────────────────────────

/**
 * Get background transform for the current progress.
 *
 * @param effect — background effect name
 * @param progress — scene progress 0→1
 * @param beatIntensity — 0→1 for beat-reactive effects
 * @param sceneIndex — used to alternate direction for ken-burns/drift
 */
export function getBackgroundTransform(
  effect: string | undefined,
  progress: number,
  beatIntensity = 0,
  sceneIndex = 0,
): BackgroundTransform {
  const dir = DIRECTIONS[sceneIndex % DIRECTIONS.length];

  // Undefined falls through to slow-zoom-in. Previously the missing
  // case landed in the `default:` branch alongside `"static"`, returning
  // `transform: "none"` — so every video where the AI didn't set
  // backgroundEffect (i.e. nearly all of them) rendered with zero
  // motion while the editor UI displayed "Slow zoom in" as default.
  // Now renderer and UI agree: `undefined` means motion, `"static"`
  // is the explicit opt-out. Slow zoom in (scale 1.00 → 1.12, no
  // translate) is the safest default for 2-4 s scenes — visible
  // enough to register, gentle enough not to pull focus from text.
  // Ken Burns adds translate that's too fast on short clips; reserve
  // for longer photo scenes via an explicit opt-in.
  const resolved = effect ?? "slow-zoom-in";

  switch (resolved) {
    case "slow-zoom-in":
      return {
        transform: `scale(${interpolate(progress, [0, 1], [1, 1.12])})`,
        transformOrigin: "center",
      };

    case "slow-zoom-out":
      return {
        transform: `scale(${interpolate(progress, [0, 1], [1.12, 1])})`,
        transformOrigin: "center",
      };

    case "ken-burns":
      return getKenBurnsTransform(progress, dir);

    case "drift":
      return getDriftTransform(progress, dir);

    case "pulse": {
      // Subtle scale pulse synced to beat
      const base = 1 + beatIntensity * 0.04;
      const breathe = 1 + Math.sin(progress * Math.PI * 2) * 0.02;
      return {
        transform: `scale(${base * breathe})`,
        transformOrigin: "center",
      };
    }

    case "breathe": {
      // Slow ambient float — gentle scale + vertical drift, not beat-synced
      const s = 1 + Math.sin(progress * Math.PI) * 0.03;
      const y = Math.sin(progress * Math.PI) * 0.5;
      return {
        transform: `scale(${s}) translateY(${y}%)`,
        transformOrigin: "center",
      };
    }

    case "slow-tilt": {
      // Subtle Dutch angle drift
      const angle = interpolate(progress, [0, 1], [0, 2.5]);
      return {
        transform: `scale(1.08) rotate(${angle}deg)`,
        transformOrigin: "center",
      };
    }

    case "camera-shake": {
      // Rapid small offsets for handheld/dramatic feel
      // Deterministic noise based on progress for reproducibility
      const t = progress * 40;
      const sx = Math.sin(t * 2.3) * 0.4 + Math.sin(t * 5.7) * 0.2;
      const sy = Math.cos(t * 3.1) * 0.3 + Math.cos(t * 4.9) * 0.15;
      const sr = Math.sin(t * 1.7) * 0.3;
      return {
        transform: `scale(1.05) translate(${sx}%, ${sy}%) rotate(${sr}deg)`,
        transformOrigin: "center",
      };
    }

    case "static":
    default:
      return {
        transform: "none",
        transformOrigin: "center",
      };
  }
}

/**
 * Color utilities for scene templates.
 *
 * Provides safe color manipulation that works with hex colors
 * and graceful fallbacks for non-hex inputs.
 */
import React from "react";
import type { GlobalStyle } from "../video-config";
import { resolveTokens } from "./tokens";

// ─── Layout constants ───────────────────────────────────────
//
// Shared vertical layout for templates that place a TextOverlay at the top of
// the scene (showcase-*, chart-*, infographic-*). Using a single constant
// guarantees the headline sits in the same place across every template, so
// scene-to-scene cuts don't visually jump.
//
// TextOverlay vertically centers itself inside its container, so the visual
// midline of the headline = TOP_TEXT_AREA_RATIO / 2 of the scene height.
export const TOP_TEXT_AREA_RATIO = 0.32;

/**
 * Convert a hex color + opacity (0-1) to an rgba() string.
 * Handles 3-digit (#abc) and 6-digit (#aabbcc) hex.
 * Falls back to the raw color with opacity if not parseable as hex.
 */
export function withOpacity(hex: string, opacity: number): string {
  const match = hex.match(/^#([0-9a-f]{3,8})$/i);
  if (!match) return hex; // Not hex — return as-is

  let r: number, g: number, b: number;
  const h = match[1];

  if (h.length === 3) {
    r = parseInt(h[0] + h[0], 16);
    g = parseInt(h[1] + h[1], 16);
    b = parseInt(h[2] + h[2], 16);
  } else if (h.length >= 6) {
    r = parseInt(h.slice(0, 2), 16);
    g = parseInt(h.slice(2, 4), 16);
    b = parseInt(h.slice(4, 6), 16);
  } else {
    return hex;
  }

  return `rgba(${r},${g},${b},${opacity})`;
}

/**
 * Check if a hex color is dark (luminance < 0.5).
 * Uses relative luminance formula from WCAG.
 */
export function isColorDark(hex: string): boolean {
  const match = hex.match(/^#([0-9a-f]{3,8})$/i);
  if (!match) return true; // Default to dark if not parseable

  let r: number, g: number, b: number;
  const h = match[1];

  if (h.length === 3) {
    r = parseInt(h[0] + h[0], 16);
    g = parseInt(h[1] + h[1], 16);
    b = parseInt(h[2] + h[2], 16);
  } else if (h.length >= 6) {
    r = parseInt(h.slice(0, 2), 16);
    g = parseInt(h.slice(2, 4), 16);
    b = parseInt(h.slice(4, 6), 16);
  } else {
    return true;
  }

  // Relative luminance (simplified sRGB)
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance < 0.5;
}

/**
 * Given two colors, return them ordered [darker, lighter] by relative
 * luminance. Used by gradient backgrounds so the darker stop always anchors
 * the top of the frame.
 */
export function orderDarkToLight(a: string, b: string): [string, string] {
  const lum = (hex: string): number => {
    const m = hex.match(/^#([0-9a-f]{6})$/i);
    if (!m) return 0;
    const h = m[1];
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b2 = parseInt(h.slice(4, 6), 16);
    return 0.299 * r + 0.587 * g + 0.114 * b2;
  };
  return lum(a) <= lum(b) ? [a, b] : [b, a];
}

/**
 * Auto-derive text color from background color.
 * Returns white for dark backgrounds, near-black for light ones.
 */
export function autoTextColor(bg: string): string {
  return isColorDark(bg) ? "#ffffff" : "#111111";
}

/**
 * Shift a hex color's hue by a number of degrees — canonical implementation
 * lives with the token resolver; re-exported here because every template
 * historically imports it from color-utils.
 */
export { shiftHue } from "./tokens";

/**
 * Gradient background — clean 2-color linear gradient with a subtle
 * animated breathing overlay. Matches the look of a plain CSS
 * `linear-gradient(90deg, colorA, colorB)` so palette chips preview
 * exactly what templates render.
 *
 * The animation is deliberately minimal: two low-opacity radial blobs
 * of the same two colors drift slowly, adding just enough motion for
 * video without introducing a third "midtone" color that muddies
 * the gradient (a common source of unwanted purple/brown tints).
 */
export function gradientBackground({
  colorA,
  colorB,
  solidBg,
  progress,
  sceneDuration,
  seed,
}: {
  colorA: string;
  colorB: string;
  /**
   * When set, the function returns this color as a solid background
   * (no gradient, no animated radial overlays). Used when the user has
   * a scraped brand whose darkest color reads as a real surface — the
   * accent stays on text/CTAs, but the bg goes flat instead of pairing
   * with an unrelated brand color and producing a noisy gradient.
   */
  solidBg?: string;
  progress: number;
  sceneDuration?: number;
  seed: number;
}): string {
  if (solidBg) return solidBg;
  const elapsed = progress * (sceneDuration || 3);
  const t = elapsed * 0.6;

  const seededRandom = (s: number): number => {
    const x = Math.sin(s * 12.9898 + s * 78.233) * 43758.5453;
    return x - Math.floor(x);
  };
  const phase = seededRandom(seed) * Math.PI * 2;

  const x1 = 25 + Math.sin(t + phase) * 25;
  const y1 = 30 + Math.cos(t * 0.7 + phase + 1.0) * 25;
  const x2 = 75 + Math.sin(t * 0.6 + phase + 2.0) * 25;
  const y2 = 70 + Math.cos(t * 0.4 + phase + 3.5) * 25;

  // Darker of the two colors anchors the top of the frame so text and logos
  // sit over the stronger value. 180deg = top→bottom.
  const [topColor, bottomColor] = orderDarkToLight(colorA, colorB);

  return `
    radial-gradient(ellipse 60% 60% at ${x1}% ${y1}%, ${colorA}4d 0%, transparent 65%),
    radial-gradient(ellipse 60% 60% at ${x2}% ${y2}%, ${colorB}4d 0%, transparent 65%),
    linear-gradient(180deg, ${topColor} 0%, ${bottomColor} 100%)
  `;
}

/**
 * Animated brand-gradient overlay. Drop as the first child inside a template's
 * outer container. Uses accent + secondary (or hue-shifted accent) as gradient
 * colors. When the user is in solid mode (accent = secondary = bg), the
 * gradient collapses to a flat layer — no visual effect beyond the solid bg.
 */
export const BrandGradientOverlay: React.FC<{
  style: GlobalStyle;
  progress: number;
  sceneDuration?: number;
  seed: number;
}> = ({ style: globalStyle, progress, sceneDuration, seed }) => {
  const tokens = resolveTokens(globalStyle);
  const accent = tokens.accent;
  // tokens.secondary carries the "auto" guard: an explicit kit secondary
  // passes through verbatim, but the literal string "auto" (the kit's
  // derive-for-me sentinel) resolves to shiftHue(accent, 50) instead of
  // leaking into the CSS gradient as an invalid color.
  const secondary = tokens.secondary;
  const solidBg = tokens.bg;

  return React.createElement("div", {
    style: {
      position: "absolute" as const,
      inset: 0,
      background: gradientBackground({ colorA: accent, colorB: secondary, solidBg, progress, sceneDuration, seed }),
      pointerEvents: "none" as const,
    },
  });
};

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares what variables it needs (auto-shown as input fields in the Studio)
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { GlobalStyle, VariableField, SafeZone } from "../video-config";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: GlobalStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}

/**
 * What a template can DO inside a video. A template can serve more than
 * one job — `bigNumber` is `["claim", "proof"]`; `media` is
 * `["atmosphere", "setup"]`. Used by the chat composer to pick templates
 * by scene-job rather than by the (less useful) category bucket.
 *
 * - `setup` — opens the world, names the subject, frames the question
 * - `claim` — makes a falsifiable statement the rest of the video earns
 * - `proof` — backs a claim with a number, quote, mockup, code, or chart
 * - `atmosphere` — breathing room; ties scenes together visually
 * - `payoff` — punchline, reveal, or satisfying answer to an earlier setup
 * - `punctuation` — short energy beat that breaks pattern or lands a joke
 * - `ask` — pushes the viewer to the next action; closer-territory only
 */
export type TemplateJob = "setup" | "claim" | "proof" | "atmosphere" | "payoff" | "punctuation" | "ask";

/**
 * The visual register a template lives in — what the *viewer* notices
 * before reading any copy. The chat's diversity rule reads this rather
 * than `category` because two `card-led` bodies look the same to the
 * viewer even when they're a `testimonial` and a `bigNumber`.
 *
 * - `motion-led` — animation IS the content (confetti, emoji rain, charts)
 * - `typography-led` — text fills the frame (bigNumber, ctaLogo, tripleStats)
 * - `device-led` — phone/browser/terminal frame is the focal element
 * - `card-led` — quote/feature/comparison cards
 * - `mockup-led` — full UI surface (chat thread, search results, app feed)
 */
export type TemplateRegister =
  | "motion-led"
  | "typography-led"
  | "device-led"
  | "card-led"
  | "mockup-led";

/**
 * A registered scene template.
 */
export interface SceneTemplate {
  id: string;
  /** Built-in templates leave these blank — DB owns them. Vibecoded
   *  templates carry their own here since they have no DB row. */
  label?: string;
  description?: string;
  category?: string | null;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  /** Thumbnail URL for visual picker (optional) */
  thumbnail?: string;
  /** If true, template consumes the video-level defaultTextArchetype */
  usesGlobalTextEffect: boolean;
  /** If true, template uses the video-level defaultTransition */
  usesGlobalTransition: boolean;
  /** If true, template uses the video-level defaultBackgroundEffect */
  usesGlobalBackgroundEffect: boolean;
  /**
   * Spatial budget for text effects.
   * - "tight" (default): text shares the frame with UI (mockup, chart). Expressive
   *   effects are auto-clamped to contained equivalents to prevent clipping.
   * - "open": text is the focal element (bg-* templates). All effects allowed.
   */
  textCanvas?: "tight" | "open";
  /**
   * Hard input gates — what this template needs from the user's input to fire
   * legitimately. The AI uses these to filter out templates that would force
   * it to invent content (e.g. \`bigNumber\` without a real number).
   *
   * Set to true when the template's value depends on input that the model
   * can't fabricate honestly: a stat, a quote, an uploaded screenshot.
   * Defaults to false (no constraint).
   */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  /** Template can be backed by Pexels stock footage (e.g. \`media\`). */
  allowsStockMedia?: boolean;
  /** Variable schema — Studio auto-generates inputs from this */
  variableSchema: Record<string, VariableField>;
  /** Default values for all variables */
  defaultVariables: Record<string, unknown>;
  /** Minimum scene duration in seconds */
  minDuration?: number;
  /** Recommended scene duration in seconds */
  preferredDuration?: number;
  /** The React component that renders this template */
  component: React.FC<SceneTemplateProps>;
}

/**
 * Serializable template metadata (no component) — for edge functions, API, MCP.
 */
export interface SceneTemplateMetadata {
  id: string;
  usesGlobalTextEffect: boolean;
  usesGlobalTransition: boolean;
  usesGlobalBackgroundEffect: boolean;
  textCanvas?: "tight" | "open";
  /** Hard input gates — see SceneTemplate.requiresStat etc. */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  allowsStockMedia?: boolean;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  variableSchema: Record<string, VariableField>;
  defaultVariables: Record<string, unknown>;
  minDuration?: number;
  preferredDuration?: number;
}

/**
 * VideoConfig — React template-based architecture.
 *
 * Every scene is a React template. Templates declare their variables via a schema,
 * and the Studio auto-generates input UI from it. AI picks templates by matching
 * descriptions to the user's prompt.
 */

// ─── Orientation & Dimensions ──────────────────────────────────

export type Orientation = "portrait" | "landscape";

export interface VideoDimensions {
  width: number;
  height: number;
  aspectRatio: string;
}

export interface SafeZone {
  top: number;
  bottom: number;
  left: number;
  right: number;
}

export function getDimensions(orientation: Orientation = "portrait"): VideoDimensions {
  return orientation === "landscape"
    ? { width: 1920, height: 1080, aspectRatio: "16 / 9" }
    : { width: 1080, height: 1920, aspectRatio: "9 / 16" };
}

export function getSafeZone(orientation: Orientation = "portrait"): SafeZone {
  return orientation === "landscape"
    ? { top: 108, bottom: 108, left: 192, right: 192 }    // SMPTE broadcast safe (10%)
    : { top: 100, bottom: 100, left: 60, right: 60 };     // Balanced safe zone — enough margin without eating content
}

// ─── Core Config ───────────────────────────────────────────────

export interface VideoConfig {
  orientation?: Orientation;
  audio?: AudioConfig;
  scenes: SceneConfig[];
  style: GlobalStyle;
  meta?: VideoMeta;
}

// ─── Audio ─────────────────────────────────────────────────────

export interface AudioConfig {
  trackId: string;
  audioUrl: string;
  duration: number;
  beatDetection: BeatDetectionConfig;
  beatMarkers: BeatMarker[];
  /** Volume 0.0-1.0. Default 1.0 (full track volume). */
  volume?: number;
  /** Fade-out duration in milliseconds at end of audio. When unset, falls
   *  back to min(lastSceneDuration, 3s) via `defaultFadeOutMs()` — the fade
   *  ramps down over the closer instead of cutting hard. Set explicitly
   *  (including 0) to override. */
  fadeOutMs?: number;
}

export interface BeatDetectionConfig {
  sensitivity: number;
  targetBeats?: number;
  minInterval?: number;
}

export interface BeatMarker {
  time: number;
  manual?: boolean;
  energy?: "high" | "medium" | "low";
}

// ─── Scene ─────────────────────────────────────────────────────

export interface SceneConfig {
  id: string;
  templateId: string;
  variables: Record<string, unknown>;
  /** Text archetype for this scene. One of the 6 names in TEXT_ARCHETYPES. */
  textArchetype?: string;
  // Note: scene-level transition override (formerly `transition?: string` with
  // a UI selector for crossfade / cut / slide / flash / dip / zoom) was
  // removed when none of the eight options were wired to the renderer.
  // Renderer now picks cut vs dissolve from `shouldDissolveBetween` in
  // scene-resolver.ts. Re-introduce as `transition: "cut" | "dissolve"` here
  // if real exceptions to the continuity rule appear.
  /** Override video-level default background effect (for templates that opt in) */
  backgroundEffect?: string;
  /**
   * Per-scene background override. When set, this scene renders on the
   * overridden gradient (accent + secondary) instead of the video-level
   * brand. Solid mode = accent equals secondary; gradient = distinct.
   */
  backgroundOverride?: { accent: string; secondary: string };
  timing: TimingConfig;
  /** AI-generated alternative templates with purpose-written copy. 0–3 per scene. */
  alternatives?: AlternativeTemplate[];
  /**
   * Raw React source for vibecoded (custom_*) templates. Set on save so
   * server-side render (`/render` + Trigger.dev export) can rehydrate the
   * template without the client's sessionStorage. Empty for built-in
   * templates. Stripped before display — never read at runtime in the Studio
   * (the in-memory `customTemplates` registry is the source of truth there).
   */
  componentSource?: string;
}

// ─── Alternative Template ─────────────────────────────────────

export interface AlternativeTemplate {
  templateId: string;
  variables: Record<string, unknown>;
  /** Human-readable rationale shown in the picker (e.g. "More cinematic", "Social proof angle") */
  rationale?: string;
}

// ─── Variable Schema ──────────────────────────────────────────

export interface VariableField {
  type: "string" | "number" | "boolean" | "enum" | "media" | "color" | "data-points";
  label: string;
  default?: unknown;
  /** Options for enum type */
  options?: string[];
  required?: boolean;
  /** Help text shown in Studio and used by AI for context */
  description?: string;
}

// ─── Timing ────────────────────────────────────────────────────

export interface TimingConfig {
  beatStart?: number;           // beat marker index (beat-sync mode)
  beatEnd?: number;             // beat marker index (beat-sync mode)
  startTime?: number;           // seconds (time-based mode)
  endTime?: number;             // seconds (time-based mode)
  fixedDuration?: number;       // seconds (no-audio mode)
  durationWeight?: number;      // relative weight for auto-distribution
}

// ─── Style ─────────────────────────────────────────────────────

export interface GlobalStyle {
  font: string;
  brandKit?: BrandKit;
  /** Default text archetype when a scene doesn't set one. */
  defaultTextArchetype?: string;
  /** Default transition between scenes */
  defaultTransition?: string;
  /** Default background effect — consumed by templates with usesGlobalBackgroundEffect: true */
  defaultBackgroundEffect?: string;
}

// ─── Brand Kit ────────────────────────────────────────────────

export interface BrandKit {
  /** Primary brand color — drives one half of the gradient mesh and most accents. */
  accent: string;
  /** Secondary brand color — drives the other half of the gradient mesh.
   *  When equal to accent, the gradient collapses to a flat color (solid mode). */
  secondary?: string;
  /** Optional explicit text color override — defaults to white (#ffffff) when
   *  not set. Templates render scrims/vignettes to handle bright surfaces. */
  text?: string;
  logoDataUrl?: string;
  /**
   * Solid scene background override. When set, the gradient renderer
   * collapses to this single color — used by the brand scraper when the
   * captured site has a clear dark surface (e.g., dark body text on a
   * light marketing page reads as a real navy / charcoal brand color).
   * Pairing it with `accent` in a gradient produced muddy results, so
   * we instead anchor the bg flat and let `accent` handle highlights.
   */
  bg?: string;
  /**
   * Normalized URL the brand was scraped from (undefined if the kit was
   * set manually via the brand panel). Acts as a cache key — when the
   * next prompt URL matches `sourceUrl`, skip the scrape and reuse the
   * saved kit. When it differs, scrape the new URL per-video without
   * touching the saved kit. Empty kit + URL prompt auto-promotes the
   * scrape result to the saved kit so the user has a default next session.
   */
  sourceUrl?: string;

  // ─── Extended fields for primitive composition (vibecode-v2) ──────
  /** Deepest background surface — defaults to a near-black if unset. */
  surface?: string;
  /** Elevated card / panel surface — defaults to surface + 4% lighten. */
  surface_elevated?: string;
  /** Muted text color for labels, footers, supporting copy. Default #a7a6b0. */
  muted?: string;
  /** Script accent font family for handwritten callouts (Caveat-style). Default "Caveat". */
  script_font?: string;
  /** Inferred mood/vibe from URL capture — used downstream for music selection. */
  vibe?: "default" | "reflective" | "edgy" | "playful" | "premium";
}

// ─── Gradient / Background Style (used by VideoManager, VideoCardPreview, BackgroundShowcase for saved videos) ──

export type BackgroundStyle = "solid" | "blobs" | "waves" | "blurry-gradient" | "circles" | "blob-scene" | "layered-waves" | "stacked-waves" | "blob-scatter" | "polygon-scatter" | "symbol-scatter" | "radial-gradient" | "mesh-gradient" | (string & {});

export interface PatternParams {
  complexity?: number;
  contrast?: number;
  size?: number;
  count?: number;
  balance?: number;
  variant?: "solid" | "outline";
  direction?: "up" | "down" | "left" | "right";
}

export interface GradientConfig {
  colors: [string, string];
  style: BackgroundStyle;
  animationSpeed: number;
  params?: PatternParams;
}

// ─── Meta ──────────────────────────────────────────────────────

export interface VideoMeta {
  name?: string;
  prompt?: string;
  sourceUrl?: string;
  createdAt?: string;
  mood?: string[];
  videoType?: string;
  /** Video format. Currently only "launch"; grows as new formats ship (review, milestone, etc.). */
  format?: "launch";
  trackRationale?: string;
  templateRationale?: string;
  source?: string;
  uploadedMediaUrls?: string[];
  /** Flat list of images the user uploaded on the landing page. The chat
   *  routes them to scenes via vision + setSceneMedia on turn 0. */
  uploadedImages?: string[];
  documentContent?: string;
  /** Stable identifier for the studio chat thread tied to this config.
   *  Lazily assigned the first time the user opens the chat, persisted via
   *  the same localStorage path as the rest of the config so the chat
   *  history (kept in sessionStorage under this key) can be rehydrated
   *  across tab switches and page reloads within a session. */
  chatId?: string;
  /** The `shared_configs` row this video is persisted to. Stamped when a
   *  config loads from `?config=<id>` and on the first autosave/export of a
   *  new build. Anchors continuous autosave + export to a single row
   *  (update-in-place) instead of minting a new row per save. */
  savedConfigId?: string;
  /** Stamped server-side by save-config when markExported is passed. */
  exported_at?: string;
}

// ─── Validation ────────────────────────────────────────────────

export function validateVideoConfig(config: unknown): config is VideoConfig {
  if (!config || typeof config !== "object") return false;
  const c = config as Record<string, unknown>;

  if (!Array.isArray(c.scenes) || c.scenes.length === 0) return false;
  if (!c.style || typeof c.style !== "object") return false;

  const style = c.style as Record<string, unknown>;
  if (typeof style.font !== "string") return false;

  for (const scene of c.scenes as Record<string, unknown>[]) {
    if (!scene.id || typeof scene.id !== "string") return false;
    if (!scene.templateId || typeof scene.templateId !== "string") return false;
    if (!scene.timing || typeof scene.timing !== "object") return false;
  }

  // Validate audio if present
  if (c.audio) {
    const audio = c.audio as Record<string, unknown>;
    if (typeof audio.trackId !== "string") return false;
    if (typeof audio.audioUrl !== "string") return false;
    if (typeof audio.duration !== "number") return false;
    if (!Array.isArray(audio.beatMarkers)) return false;
    if (!audio.beatDetection || typeof audio.beatDetection !== "object") return false;
  }

  return true;
}

// ─── Factory ───────────────────────────────────────────────────

export function createDefaultScene(overrides?: Partial<SceneConfig>): SceneConfig {
  return {
    id: crypto.randomUUID(),
    templateId: "media",
    variables: {
      texts: "",
      mediaUrl: "",
      mediaKeyword: "",
    },
    timing: { fixedDuration: 3 },
    ...overrides,
  };
}
